func redisTLSConfig(cfg config.RedisCacheConfig) (*tls.Config, error) {
	if cfg.CaCertPath != "" && len(cfg.CaCertBytes) > 0 {
		return nil, errors.New(exclusiveCACertError)
	}
	if !cfg.RequireTLS {
		return nil, nil
	}

	tlsConfig := &tls.Config{
